      const b = document.createElement("span"), earned = mission.completed.some((r) => r.id === l.id);
      b.className = earned ? "earned" : "";
      b.textContent = earned ? "\u2713 " + l.badge : String(i + 1);
      b.title = earned ? l.skill : l.badge + " \xB7 complete level " + (i + 1);
