    $("world-subtitle").textContent = renderer.mode === "solar" ? "Drag for a 360\xB0 orbit \xB7 distances compressed \xB7 bodies enlarged" : renderer.mode === "orbital" ? "Observation view \xB7 use Return to play to move on the surface" : s.status === "ready" ? mission.lesson.skill : next.title;
